 check(rigid==3&&skins.size()>1,"Real source includes multiple distinct authored skins and three rigid node/mesh instances");check(scene.encode()==before,"Graph normalization performs no authoring mutation or source-byte rewrite");const auto head=uint32_t(rigid_nodes.head);auto agreement=graph.pose_agreement(head);check(agreement.agreement==detail::SourcePoseAgreement::Shared&&agreement.shared,"Initially shared original-head pose is explicitly proved");
